mapper.sql:
WHERE u.del_flag = '0'

    AND (u.user_name ILIKE CONCAT('%', #{keyword}, '%')
        OR u.nick_name ILIKE CONCAT('%', #{keyword}, '%') OR u.email ILIKE CONCAT('%', #{keyword}, '%'))

AND () = #{role}
AND u.status = #{status}

    AND (u.user_id = #{actorId} OR (() = 'common' AND NOT EXISTS (
        SELECT 1 FROM sys_user_role ur JOIN sys_role r ON r.role_id = ur.role_id
        WHERE ur.user_id = u.user_id AND r.del_flag = '0' AND r.role_key != 'common'
    )))

mapper.select:
SELECT user_id FROM sys_user WHERE user_id IN
#{id}
ORDER BY user_id FOR UPDATE
